"""Which harness a run exercised: keel linked into the CLI's config dir, or the previous one (the eval's config guard)."""
from __future__ import annotations

import hashlib
import os
import re

# Mirrors lib/link/claude_md.py HEADER; measure must not import lib/link (Interfaces (a)).
GENERATED_CLAUDE_MD_HEADER = (
    "<!-- GENERATED by keel bin/link from PRINCIPLES.md + PERSONAL.md. "
    "Edit the sources, then run bin/link --write. -->"
)
V1_BASELINE_SUFFIX = "-v1baseline"
PROJECT_SLUG_CHARS = re.compile(r"[^A-Za-z0-9]")


def cli_config_dir() -> str:
    return os.environ.get("CLAUDE_CONFIG_DIR") or os.path.expanduser("~/.claude")


def is_keel_live(config_dir: str, keel_home: str, skill: str) -> bool:
    """The skill under test is a symlink into keel_home and CLAUDE.md is keel's generated file."""
    skill_link = os.path.join(config_dir, "skills", skill)
    return _links_into(skill_link, keel_home) and _is_generated(os.path.join(config_dir, "CLAUDE.md"))


def suite_eval_id(eval_id: str, keel_live: bool) -> str:
    return eval_id if keel_live else eval_id + V1_BASELINE_SUFFIX


def config_fingerprint(config_dir: str, skill: str) -> dict:
    return {
        "claude_md_sha256": _sha256(os.path.join(config_dir, "CLAUDE.md")),
        "skill_md_sha256": _sha256(os.path.join(config_dir, "skills", skill, "SKILL.md")),
    }


def project_dir_for(cwd: str, config_dir: str) -> str:
    """Where the CLI keeps a cwd's project data: its realpath with every non-alphanumeric character turned into '-'."""
    return os.path.join(config_dir, "projects", PROJECT_SLUG_CHARS.sub("-", os.path.realpath(cwd)))


def _links_into(path: str, root: str) -> bool:
    if not os.path.islink(path):
        return False
    pointee, real_root = os.path.realpath(path), os.path.realpath(root)
    return pointee == real_root or pointee.startswith(real_root + os.sep)


def _is_generated(path: str) -> bool:
    if os.path.islink(path) or not os.path.isfile(path):
        return False
    with open(path, encoding="utf-8", newline="") as handle:
        return handle.readline().rstrip("\n") == GENERATED_CLAUDE_MD_HEADER


def _sha256(path: str) -> str | None:
    if not os.path.isfile(path):
        return None
    with open(path, "rb") as handle:
        return hashlib.sha256(handle.read()).hexdigest()
